	private void runQuery(WorkbenchRequest req, SectionRequest selection, Value resource,
			RepositoryConnection connection, TupleResultBuilder builder, CancellableOperationCoordinator.Handle handle,
			AtomicBoolean remoteStarted, long started, SectionOperation operation, boolean physical) throws Exception {
		if (!operation.active(handle)) {
			return;
		}
		long remaining = remainingNanos(started);
		if (remaining <= 0) {
			throw new OperationTimedOutException(BrowseList.timedOutMessage("Exploring"));
		}
		int seconds = (int) Math.max(1, Math.min(Integer.MAX_VALUE,
				TimeUnit.NANOSECONDS.toSeconds(remaining - 1) + 1));
		ExploreQuery spec = ExploreQuery.create(selection.section, selection.count, selection.scope,
				selection.limit, physical, resource, req.getParameterValues("language"),
				connection.getValueFactory());
		TupleQuery query = spec.prepare(connection, seconds);
		if (!operation.active(handle)) {
			return;
		}
		remoteStarted.set(true);
		if (!operation.active(handle)) {
			return;
		}
		try (TupleQueryResult result = query.evaluate()) {
			if (selection.count) {
				if (!result.hasNext()) {
					throw new RepositoryException("Explore count did not return a value");
				}
				Value total = result.next().getValue("total");
				if (!(total instanceof Literal literal)) {
					throw new RepositoryException("Explore count did not return an integer");
				}
				BigInteger count = literal.integerValue();
				if (count.signum() < 0) {
					throw new RepositoryException("Explore count was negative");
				}
				operation.publish(handle, () -> builder.metadata("explore-count", count.toString()));
			} else {
				String[] variables = selection.variables();
				for (int emitted = 0; emitted < selection.limit && handle.isActive()
						&& result.hasNext(); emitted++) {
					BindingSet row = result.next();
					Value[] values = new Value[variables.length];
					for (int i = 0; i < variables.length; i++) {
						values[i] = row.getValue(variables[i]);
					}
					if (!operation.publish(handle, () -> builder.result((Object[]) values))) {
						return;
					}
				}
			}
		}
	}

	private Semaphore admission(boolean count) {
		Map<Repository, Semaphore> limits = count ? COUNT_ADMISSION : PAGE_ADMISSION;
		int maximum = count ? BrowseList.MAX_IN_FLIGHT_COUNTS : BrowseList.MAX_IN_FLIGHT_PAGE_OPERATIONS;
		synchronized (limits) {
			return limits.computeIfAbsent(repository, ignored -> new Semaphore(maximum, true));
		}
	}

	private long remainingNanos(long started) {
		return TimeUnit.MILLISECONDS.toNanos(budgetMillis) - (System.nanoTime() - started);
	}

	private boolean physical(CancellableOperationCoordinator.Handle handle) throws InterruptedException {
		Boolean mode = physicalGraphMode;
		if (mode == null) {
			graphModeLock.lockInterruptibly();
			try {
				mode = physicalGraphMode;
				if (mode == null) {
					if (handle != null && !handle.isActive()) {
						return false;
					}
					mode = ExploreGraphMode.physical(repository, manager, info == null ? null : info.getId());
					if ((handle == null || handle.isActive()) && !Thread.currentThread().isInterrupted()) {
						physicalGraphMode = mode;
					}
				}
			} finally {
				graphModeLock.unlock();
			}
		}
		return mode;
	}

	private TupleResultBuilder sectionBuilder(WorkbenchRequest req, HttpServletResponse resp, OutputStream output)
			throws IOException, QueryResultHandlerException {
		WorkbenchPageProtocol.configureDynamicPageResponse(resp);
		resp.setContentType(WorkbenchPageProtocol.CONTENT_TYPE);
		WorkbenchPageResultWriter writer = new WorkbenchPageResultWriter(output);
		req.setAttribute(WorkbenchPageProtocol.PAGE_RESULT_WRITER_ATTRIBUTE, writer);
		writer.view("explore");
		writer.metadata(WorkbenchPageProtocol.SERVER_IDENTITY_METADATA,
				req.getAttribute(WorkbenchPageProtocol.SERVER_IDENTITY_ATTRIBUTE));
		writer.metadata(WorkbenchPageProtocol.SERVER_USER_METADATA,
				req.getAttribute(WorkbenchPageProtocol.SERVER_USER_ATTRIBUTE));
		return new TupleResultBuilder(writer, SimpleValueFactory.getInstance());
	}

	private void writeFailure(WorkbenchRequest req, HttpServletResponse resp, QueryResponseHeartbeat heartbeat,
			int status, String message) throws IOException, QueryResultHandlerException {
		if (!resp.isCommitted()) {
			resp.setStatus(status);
		}
		Object existing = req.getAttribute(WorkbenchPageProtocol.PAGE_RESULT_WRITER_ATTRIBUTE);
		if (!(existing instanceof WorkbenchPageResultWriter)) {
			if (!hasRequestParameter(req, "section") && !WorkbenchPageProtocol.requestsPageData(req)) {
				resp.sendError(status, message);
				return;
			}
			TupleResultBuilder builder = sectionBuilder(req, resp,
					heartbeat == null ? resp.getOutputStream() : heartbeat.getOutputStream());
			builder.start();
			existing = req.getAttribute(WorkbenchPageProtocol.PAGE_RESULT_WRITER_ATTRIBUTE);
		}
		((WorkbenchPageResultWriter) existing).error(status, message == null ? "Explore request failed" : message);
		if (heartbeat != null) {
			heartbeat.complete();
		}
	}

	@Override
	protected void doPost(WorkbenchRequest req, HttpServletResponse resp) throws IOException {
		if (!"cancel-query".equals(req.getParameter("action"))) {
			resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Expected action=cancel-query");
			return;
		}
		String id = requestId(req);
		if (id == null) {
			resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing parameter: " + REQUEST_ID);
			return;
		}
		try {
			coordinator.cancel(repositoryScope(), id);
			// Cleanup can arrive after the section has already completed or has been cancelled.
			resp.setStatus(HttpServletResponse.SC_NO_CONTENT);
		} catch (CancellableOperationCoordinator.CancellationException failure) {
			if (failure.getCause() instanceof QueryCancellationNotFoundException) {
				// The server may not have registered the query yet. Cleanup is accepted while the coordinator retries.
				resp.setStatus(HttpServletResponse.SC_NO_CONTENT);
			} else {
				resp.sendError(HttpServletResponse.SC_BAD_GATEWAY, failure.getMessage());
			}
		}
	}

	private static String requestId(WorkbenchRequest request) {
		String id = request.getParameter(REQUEST_ID);
		return id == null || id.isBlank() ? null : id.trim();
	}

	/** Distinguish an omitted selector from one explicitly supplied with an empty value. */
	private static boolean hasRequestParameter(WorkbenchRequest request, String name) {
		return request.getParameterValues(name) != null;
	}

	private String repositoryScope() {
		return info == null || info.getId() == null ? "" : info.getId();
	}

	private Runnable remoteCancellation(String id, AtomicBoolean remoteStarted) {
		Set<Repository> visited = Collections.newSetFromMap(new IdentityHashMap<>());
		Repository current = repository;
		while (current != null && visited.add(current)) {
			if (current instanceof HTTPRepository http) {
				return () -> {
					if (remoteStarted.get()) {
						try {
							http.cancelQuery(id);
						} catch (RepositoryException failure) {
							throw new CancellableOperationCoordinator.CancellationException(
									"Remote Explore cancellation failed for request " + id, failure);
						}
					}
				};
			}
			current = current instanceof DelegatingRepository wrapper ? wrapper.getDelegate() : null;
		}
		return null;
	}

	@Override
	public void destroy() {
		try {
			coordinator.shutdown();
		} finally {
			super.destroy();
		}
	}

	private record SectionRequest(Section section, boolean count, String scope, int limit) {
		static SectionRequest parse(WorkbenchRequest req) throws BadRequestException {
			Section section = Section.find(req.getParameter("section"));
			if (section == null) {
				throw new BadRequestException("Unknown Explore section");
			}
			String kind = req.getParameter("kind");
			if (!"rows".equals(kind) && !"count".equals(kind)) {
				throw new BadRequestException("Explore kind must be rows or count");
			}
			boolean count = "count".equals(kind);
			if (count && section.scalar()) {
				throw new BadRequestException("Labels and comments have no count request");
			}
			String scope = hasRequestParameter(req, "scope") ? req.getParameter("scope") : null;
			if (count && section.role() && section != Section.GRAPH) {
				if (!"default".equals(scope) && !"named".equals(scope)) {
					throw new BadRequestException("A role count requires default or named scope");
				}
			} else if (scope != null && !(count && section == Section.GRAPH && "named".equals(scope))) {
				throw new BadRequestException("Scope is not valid for this Explore request");
			}
			String load = hasRequestParameter(req, "load") ? req.getParameter("load") : "initial";
			if (!"initial".equals(load) && !"more".equals(load)) {
				throw new BadRequestException("Explore load must be initial or more");
			}
			if (count && hasRequestParameter(req, "load")) {
				throw new BadRequestException("A count request cannot select a load tier");
			}
			int limit = section.scalar() ? 1
					: "more".equals(load) ? ExploreQuery.MORE_LIMIT : ExploreQuery.INITIAL_LIMIT;
			return new SectionRequest(section, count, scope, limit);
		}

		String[] variables() {
			return count ? new String[0] : section.role() ? ROLE_VARIABLES : VALUE_VARIABLES;
		}
	}
